routes=['/','/guides/','/about/','/privacy/','/terms/']+['/guides/'+s+'/' for s,_,_,_ in guides]
(root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{origin}{p}</loc><lastmod>2026-10-02</lastmod></url>' for p in routes)+'</urlset>')
(root/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+origin+'/sitemap.xml\n')
